#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemver.h"


/* Array initialization.
 *
 * Optimizations:
 *  - Use restrict-qualified local aliases to help the compiler assume
 *    non-aliasing between arguments.
 *  - Parallelize the outer loop with OpenMP (if enabled) – iterations
 *    are fully independent.
 *  - Hoist the row pointer A_[i] to avoid repeated address arithmetic.
 */
static
void init_array (int n,
		 DATA_TYPE *alpha,
		 DATA_TYPE *beta,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_1D(u1,N,n),
		 DATA_TYPE POLYBENCH_1D(v1,N,n),
		 DATA_TYPE POLYBENCH_1D(u2,N,n),
		 DATA_TYPE POLYBENCH_1D(v2,N,n),
		 DATA_TYPE POLYBENCH_1D(w,N,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

  *alpha = 1.5;
  *beta  = 1.2;

  DATA_TYPE fn = (DATA_TYPE)n;

  /* Local restrict-qualified aliases for better optimization. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE *restrict u1_ = u1;
  DATA_TYPE *restrict v1_ = v1;
  DATA_TYPE *restrict u2_ = u2;
  DATA_TYPE *restrict v2_ = v2;
  DATA_TYPE *restrict w_  = w;
  DATA_TYPE *restrict x_  = x;
  DATA_TYPE *restrict y_  = y;
  DATA_TYPE *restrict z_  = z;

  /* Each iteration of i initializes independent rows and vector
     elements, so we can safely parallelize over i. */
#pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < n; i++)
    {
      DATA_TYPE *restrict Ai = A_[i];

      u1_[i] = (DATA_TYPE)i;
      u2_[i] = ((i+1)/fn)/2.0;
      v1_[i] = ((i+1)/fn)/4.0;
      v2_[i] = ((i+1)/fn)/6.0;
      y_[i]  = ((i+1)/fn)/8.0;
      z_[i]  = ((i+1)/fn)/9.0;
      x_[i]  = 0.0;
      w_[i]  = 0.0;

      for (j = 0; j < n; j++)
        Ai[j] = (DATA_TYPE)((i*j) % n) / (DATA_TYPE)n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(w,N,n))
{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("w");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, w[i]);
  }
  POLYBENCH_DUMP_END("w");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations:
 *  - Introduce restrict-qualified local aliases for all arrays to
 *    help the compiler assume no aliasing between them.
 *  - Precompute beta * y once in an O(n) pass, avoiding redundant
 *    multiplications inside the O(n^2) matrix-vector product.
 *  - Hoist frequently-used values (rows of A, scalars like u1[i],
 *    u2[i], x[i], w[i]) into local scalars to reduce memory traffic.
 *  - Keep memory access patterns for A row-major where possible
 *    (updates of A and computation of w), which improves cache
 *    locality and enables vectorization.
 *  - Parallelize all outer loops over i with OpenMP. Each iteration
 *    updates different elements of A, x, or w with no cross-iteration
 *    dependencies, so this is safe.
 *
 * Note: OpenMP pragmas are ignored if the code is compiled without
 *       -fopenmp, so the code remains valid and correct in that case.
 */
static
void kernel_gemver[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

  /* Local restrict-qualified aliases to help vectorization and
     common-subexpression elimination.  All of these arrays are
     disjoint in the PolyBench framework. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE *restrict u1_ = u1;
  DATA_TYPE *restrict v1_ = v1;
  DATA_TYPE *restrict u2_ = u2;
  DATA_TYPE *restrict v2_ = v2;
  DATA_TYPE *restrict w_  = w;
  DATA_TYPE *restrict x_  = x;
  DATA_TYPE *restrict y_  = y;
  DATA_TYPE *restrict z_  = z;

  /* In PolyBench, _PB_N is a macro that expands to the loop bound
     based on the problem size n (possibly scaled).  Using a local
     constant avoids re-expanding the macro in every loop header. */
  const int nn = _PB_N;

  /* Precompute beta * y once. This removes one multiplication from
     the innermost O(n^2) loop computing x, without changing the
     numerical order of accumulation.  The extra storage is O(n),
     which is negligible compared to the original O(n^2) storage. */
  DATA_TYPE beta_y[n];
  for (i = 0; i < nn; i++)
    beta_y[i] = beta * y_[i];

#pragma scop

  /* 1. A = A + u1 * v1^T + u2 * v2^T
   *
   * Original:
   *   for i
   *     for j
   *       A[i][j] = A[i][j] + u1[i]*v1[j] + u2[i]*v2[j];
   *
   * Optimized:
   *   - Parallelized outer loop over i.
   *   - Hoisted A[i] row pointer and u1[i], u2[i] to scalars.
   *   - Inner loop still scans A row-contiguously for good locality.
   */
#pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < nn; i++)
  {
    DATA_TYPE *restrict Ai = A_[i];
    const DATA_TYPE u1_i = u1_[i];
    const DATA_TYPE u2_i = u2_[i];

    for (j = 0; j < nn; j++)
    {
      Ai[j] += u1_i * v1_[j] + u2_i * v2_[j];
    }
  }

  /* 2. x = x + beta * A^T * y
   *
   * Original:
   *   for i
   *     for j
   *       x[i] = x[i] + beta * A[j][i] * y[j];
   *
   * Optimized:
   *   - The mathematical operation is unchanged: for each i, we
   *     accumulate over j in the same order.
   *   - Use precomputed beta_y[j] to remove one multiply from the
   *     inner loop.
   *   - Hoist x[i] to a scalar accumulator, reducing memory traffic.
   *   - Parallelize outer loop over i (each x[i] is independent).
   */
#pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < nn; i++)
  {
    DATA_TYPE xi = x_[i];

    for (j = 0; j < nn; j++)
    {
      xi += A_[j][i] * beta_y[j];
    }

    x_[i] = xi;
  }

  /* 3. x = x + z
   *
   * Simple element-wise vector addition. Parallelized over i.
   */
#pragma omp parallel for schedule(static)
  for (i = 0; i < nn; i++)
  {
    x_[i] += z_[i];
  }

  /* 4. w = w + alpha * A * x
   *
   * Original:
   *   for i
   *     for j
   *       w[i] = w[i] + alpha * A[i][j] * x[j];
   *
   * Optimized:
   *   - Hoist A[i] row pointer and w[i] to scalars for each i.
   *   - Access A row-contiguously (A[i][j]) to exploit cache lines.
   *   - Parallelize outer loop over i (each w[i] is independent).
   */
#pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < nn; i++)
  {
    const DATA_TYPE *restrict Ai = A_[i];
    DATA_TYPE wi = w_[i];

    for (j = 0; j < nn; j++)
    {
      wi += alpha * Ai[j] * x_[j];
    }

    w_[i] = wi;
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(u1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(u2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(w, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(z, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(u1),
	      POLYBENCH_ARRAY(v1),
	      POLYBENCH_ARRAY(u2),
	      POLYBENCH_ARRAY(v2),
	      POLYBENCH_ARRAY(w),
	      POLYBENCH_ARRAY(x),
	      POLYBENCH_ARRAY(y),
	      POLYBENCH_ARRAY(z));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gemver (n, alpha, beta,
		 POLYBENCH_ARRAY(A),
		 POLYBENCH_ARRAY(u1),
		 POLYBENCH_ARRAY(v1),
		 POLYBENCH_ARRAY(u2),
		 POLYBENCH_ARRAY(v2),
		 POLYBENCH_ARRAY(w),
		 POLYBENCH_ARRAY(x),
		 POLYBENCH_ARRAY(y),
		 POLYBENCH_ARRAY(z));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(w)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(u1);
  POLYBENCH_FREE_ARRAY(v1);
  POLYBENCH_FREE_ARRAY(u2);
  POLYBENCH_FREE_ARRAY(v2);
  POLYBENCH_FREE_ARRAY(w);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(z);

  return 0;
}
