#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemver.h"


/* Array initialization.
 *
 * Optimizations:
 *  - Hoist the common subexpression (i+1)/n so it is computed once per i.
 *  - Use a single division per i instead of several.
 *  - Use a parallel outer loop over i (rows) – each iteration writes to
 *    a distinct subset of the arrays, so this is race-free.
 *  - Keep the mathematical expression for A[i][j] identical; only reuse
 *    the precomputed floating-point value of n.
 */
static
void init_array (int n,
		 DATA_TYPE *alpha,
		 DATA_TYPE *beta,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_1D(u1,N,n),
		 DATA_TYPE POLYBENCH_1D(v1,N,n),
		 DATA_TYPE POLYBENCH_1D(u2,N,n),
		 DATA_TYPE POLYBENCH_1D(v2,N,n),
		 DATA_TYPE POLYBENCH_1D(w,N,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

  *alpha = 1.5;
  *beta  = 1.2;

  DATA_TYPE fn = (DATA_TYPE)n;

  /* Parallelize over rows. Each iteration writes to disjoint indices. */
#pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < n; i++)
