      DATA_TYPE t = ((DATA_TYPE)(i + 1)) / fn;

      u1[i] = (DATA_TYPE)i;
      u2[i] = t / 2.0;
      v1[i] = t / 4.0;
      v2[i] = t / 6.0;
      y[i]  = t / 8.0;
      z[i]  = t / 9.0;
      x[i]  = 0.0;
      w[i]  = 0.0;

      for (j = 0; j < n; j++)
