static
void kernel_gemver[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

#pragma scop

  /* Single parallel region for all four phases. When compiled without
   * OpenMP support, these pragmas are ignored and the code behaves
   * purely sequentially with identical semantics.
   */
#pragma omp parallel private(i,j)
  {
    /* 1) Rank-2 update:
     *    A[i][j] += u1[i] * v1[j] + u2[i] * v2[j]
     */
#pragma omp for schedule(static)
    for (i = 0; i < _PB_N; i++)
      {
        DATA_TYPE *restrict Ai = A[i];
        const DATA_TYPE u1_i = u1[i];
        const DATA_TYPE u2_i = u2[i];

        /* Inner loop is over the contiguous dimension j. */
#pragma omp simd
        for (j = 0; j < _PB_N; j++)
          Ai[j] += u1_i * v1[j] + u2_i * v2[j];
      }

    /* 2) x = x + beta * A^T * y
     *
     * Original:
     *   for (i)
     *     for (j)
     *       x[i] += beta * A[j][i] * y[j];
     *
     * We keep the same nesting order, but accumulate into a local
     * scalar xi to avoid repeated loads/stores of x[i]. The sequence
     * of additions for each x[i] (j = 0..N-1) is unchanged.
     */
#pragma omp for schedule(static)
    for (i = 0; i < _PB_N; i++)
      {
        DATA_TYPE xi = x[i];

        for (j = 0; j < _PB_N; j++)
          xi += beta * A[j][i] * y[j];

        x[i] = xi;
      }

    /* 3) x = x + z
     *    Each element is updated independently; parallelization is
     *    straightforward.
     */
#pragma omp for schedule(static)
    for (i = 0; i < _PB_N; i++)
      x[i] += z[i];

    /* 4) w = w + alpha * A * x
     *
     * Original:
     *   for (i)
     *     for (j)
     *       w[i] += alpha * A[i][j] * x[j];
     *
     * Again, we keep the same traversal order and use a local accumulator
     * wi per row to minimize memory traffic on w[i].
     */
#pragma omp for schedule(static)
    for (i = 0; i < _PB_N; i++)
      {
        DATA_TYPE *restrict Ai = A[i];
        DATA_TYPE wi = w[i];

        /* Inner loop over contiguous j for good cache behavior. */
#pragma omp simd
        for (j = 0; j < _PB_N; j++)
          wi += alpha * Ai[j] * x[j];

        w[i] = wi;
      }
  } /* end OpenMP parallel region */

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(u1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(u2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(w, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(z, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(u1),
	      POLYBENCH_ARRAY(v1),
	      POLYBENCH_ARRAY(u2),
	      POLYBENCH_ARRAY(v2),
	      POLYBENCH_ARRAY(w),
	      POLYBENCH_ARRAY(x),
	      POLYBENCH_ARRAY(y),
	      POLYBENCH_ARRAY(z));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gemver (n, alpha, beta,
		 POLYBENCH_ARRAY(A),
		 POLYBENCH_ARRAY(u1),
		 POLYBENCH_ARRAY(v1),
		 POLYBENCH_ARRAY(u2),
		 POLYBENCH_ARRAY(v2),
		 POLYBENCH_ARRAY(w),
		 POLYBENCH_ARRAY(x),
		 POLYBENCH_ARRAY(y),
		 POLYBENCH_ARRAY(z));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(w)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(u1);
  POLYBENCH_FREE_ARRAY(v1);
  POLYBENCH_FREE_ARRAY(u2);
  POLYBENCH_FREE_ARRAY(v2);
  POLYBENCH_FREE_ARRAY(w);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(z);

