    {
      DATA_TYPE beta_yj = beta * y[j];
      DATA_TYPE* Aj = A[j]; /* Row j of A, contiguous in memory. */

      for (i = 0; i < NPB; i++)
        x[i] = x[i] + beta_yj * Aj[i];
    }

  /* x[i] = x[i] + z[i]; */
#pragma omp parallel for schedule(static)
  for (i = 0; i < NPB; i++)
    x[i] = x[i] + z[i];

  /* w[i] = w[i] + alpha * A[i][j] * x[j]; */
#pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < NPB; i++)
    {
      DATA_TYPE wi = w[i];
      DATA_TYPE* Ai = A[i];

      /* Inner loop: contiguous access to A's row i and streaming x. */
      for (j = 0; j < NPB; j++)
        wi = wi + alpha * Ai[j] * x[j];

      w[i] = wi;
    }

#pragma endscop
}


